from __future__ import annotations

import base64
import math
import os
import time
from typing import TYPE_CHECKING

import pyray as rl

from openpilot.common.hardware import HARDWARE
from openpilot.system.ui.lib.application import gui_app
from openpilot.system.ui.widgets import Widget

if TYPE_CHECKING:
  from openpilot.common.params import Params
else:
  try:
    from openpilot.common.params import Params
  except (ImportError, OSError):
    Params = None

R_LOGO_B64 = ""  # noqa: E501

GARYPILOT_LOGO_B64 = ""  # noqa: E501

R_LOGO_PATH = "/tmp/r_logo_screensaver.png"
GARYPILOT_LOGO_PATH = "/tmp/garypilot_screensaver_logo.png"
RIVIAN_SPRITE_PATH = "/tmp/rivian_screensaver_sprite.png"

RIVIAN_SPRITE_B64 = ""  # noqa: E501


def ensure_screensaver_assets() -> tuple[str, str, str]:
  r_data = base64.b64decode(R_LOGO_B64)
  if not os.path.exists(R_LOGO_PATH) or os.path.getsize(R_LOGO_PATH) != len(r_data):
    with open(R_LOGO_PATH, "wb") as f:
      f.write(r_data)

  gp_data = None
  try:
    from fork.scripts.generate_screensaver_badge import generate_badge_png_bytes
    gp_data = generate_badge_png_bytes()
  except Exception:
    pass

  if gp_data is None:
    gp_data = base64.b64decode(GARYPILOT_LOGO_B64)

  if not os.path.exists(GARYPILOT_LOGO_PATH) or os.path.getsize(GARYPILOT_LOGO_PATH) != len(gp_data):
    with open(GARYPILOT_LOGO_PATH, "wb") as f:
      f.write(gp_data)

  rivian_data = None
  try:
    from fork.scripts.generate_screensaver_badge import generate_rivian_png_bytes
    rivian_data = generate_rivian_png_bytes()
  except Exception:
    pass

  if rivian_data is None:
    rivian_data = base64.b64decode(RIVIAN_SPRITE_B64)

  if not os.path.exists(RIVIAN_SPRITE_PATH) or os.path.getsize(RIVIAN_SPRITE_PATH) != len(rivian_data):
    with open(RIVIAN_SPRITE_PATH, "wb") as f:
      f.write(rivian_data)

  return R_LOGO_PATH, GARYPILOT_LOGO_PATH, RIVIAN_SPRITE_PATH


def draw_diamond_star(cx: float, cy: float, size: float, alpha: float) -> None:
  """Draw an authentic 4-pointed retro chrome specular star glint."""
  if size <= 0.5 or alpha <= 0.01:
    return
  a = int(alpha * 255)
  c = rl.Color(255, 255, 255, a)
  glow_c = rl.Color(180, 230, 255, int(alpha * 130))

  # Ambient soft glow halo behind the star
  rl.draw_circle(int(cx), int(cy), size * 0.55, glow_c)

  # 4 tapered diamond spikes along the primary axes
  w = max(1.2, size * 0.14)
  rl.draw_triangle(rl.Vector2(cx, cy - size), rl.Vector2(cx - w, cy), rl.Vector2(cx + w, cy), c)
  rl.draw_triangle(rl.Vector2(cx, cy + size), rl.Vector2(cx + w, cy), rl.Vector2(cx - w, cy), c)
  rl.draw_triangle(rl.Vector2(cx - size, cy), rl.Vector2(cx, cy + w), rl.Vector2(cx, cy - w), c)
  rl.draw_triangle(rl.Vector2(cx + size, cy), rl.Vector2(cx, cy - w), rl.Vector2(cx, cy + w), c)

  # 45-degree diagonal secondary rays
  diag = size * 0.42
  dw = max(1.0, size * 0.08)
  rl.draw_line_ex(rl.Vector2(cx - diag, cy - diag), rl.Vector2(cx + diag, cy + diag), dw, c)
  rl.draw_line_ex(rl.Vector2(cx - diag, cy + diag), rl.Vector2(cx + diag, cy - diag), dw, c)

  # Brilliant center core
  rl.draw_circle(int(cx), int(cy), max(1.0, size * 0.2), rl.Color(255, 255, 255, a))


def draw_screensaver(
  w: int,
  h: int,
  is_mici: bool,
  grid_offset: float = 0.0,
  texture: rl.Texture | None = None,
  gp_texture: rl.Texture | None = None,
  rivian_texture: rl.Texture | None = None,
  anim_time: float = 0.0,
) -> None:
  # Outrun Colors
  bg_color = rl.Color(13, 2, 33, 255)
  grid_color = rl.Color(255, 0, 128, 255)
  horizon_color = rl.Color(0, 255, 255, 255)

  rl.clear_background(bg_color)

  horizon_y = h // 2
  center_x = w // 2

  # Draw Stars
  rl.set_random_seed(1234)
  num_stars = 80 if not is_mici else 40
  for _ in range(num_stars):
    sx = rl.get_random_value(0, w)
    sy = rl.get_random_value(0, horizon_y - 50)
    size = rl.get_random_value(1, 2)
    alpha = rl.get_random_value(100, 255)

    if rl.get_random_value(0, 5) == 0:
      alpha = int(127 + 127 * math.sin(anim_time * 5.0 + sx))

    rl.draw_circle(sx, sy, float(size), rl.Color(255, 255, 255, alpha))

    if rl.get_random_value(0, 15) == 0:
      rl.draw_line(sx - 6, sy, sx + 6, sy, rl.Color(255, 255, 255, alpha))
      rl.draw_line(sx, sy - 6, sx, sy + 6, rl.Color(255, 255, 255, alpha))

  if texture is not None:
    # Logo as the Sun
    tex_w = texture.width
    tex_h = texture.height
    scale = 8.5 if not is_mici else 4.5

    # Offset the sun up so it is not centered on the horizon
    sun_offset_y = int((tex_h * scale) * 0.25)
    sun_y = horizon_y - sun_offset_y

    dest = rl.Rectangle(
      float(center_x - (tex_w * scale) / 2),
      float(sun_y - (tex_h * scale) / 2),
      float(tex_w * scale),
      float(tex_h * scale),
    )
    source = rl.Rectangle(0.0, 0.0, float(tex_w), float(tex_h))

    # Add a glow behind the sun using transparent circles
    glow_radius = int((tex_w * scale) * 0.6)
    for r_idx in range(25):
      r = glow_radius * (1.0 - (r_idx / 25.0))
      g_alpha = int(100 * (r_idx / 25.0))
      rl.draw_circle(center_x, sun_y, r, rl.Color(255, 100, 0, g_alpha))

    # Tint it sunset orange/yellow
    rl.draw_texture_pro(texture, source, dest, rl.Vector2(0.0, 0.0), 0.0, rl.Color(255, 204, 0, 255))

    # Draw background-color horizontal slices through the bottom half of the logo
    sun_radius = (tex_h * scale) / 2
    current_y = 0.0
    solid_thickness = 25.0 if not is_mici else 12.0
    cut_thickness = 2.0 if not is_mici else 1.0

    while current_y < sun_radius:
      current_y += solid_thickness
      slice_y = sun_y + int(current_y)

      if slice_y > horizon_y:
        break

      cut_h = int(cut_thickness)
      if cut_h < 1:
        cut_h = 1

      if slice_y + cut_h > horizon_y:
        cut_h = int(horizon_y - slice_y)

      if cut_h > 0 and slice_y > sun_y:
        rl.draw_rectangle(int(center_x - (tex_w * scale) / 2), int(slice_y), int(tex_w * scale), cut_h, bg_color)

      current_y += cut_thickness

      # Modify thicknesses for the next iteration: solid bands get thinner, cutouts get thicker
      solid_thickness *= 0.85
      cut_thickness *= 1.4

    # Strictly occlude the sun and glow if they fall below the horizon line
    rl.draw_rectangle(0, int(horizon_y), w, h - int(horizon_y), bg_color)

  # Draw Mountains
  def draw_mountain_layer(seed, color, min_dx, max_dx, min_h, max_h, y_offset, line_thick):
    rl.set_random_seed(seed)
    curr_x = -100
    pts = []
    is_peak = True
    while curr_x < w + 200:
      if is_peak:
        dx = rl.get_random_value(min_dx, max_dx)
        curr_x += dx
        dist_from_center = abs(curr_x - center_x)
        # Scale height so they are taller at edges, shorter in middle
        height_scale = 0.4 + 0.6 * (dist_from_center / (w / 2))
        height = rl.get_random_value(min_h, max_h) * height_scale
        pts.append((curr_x, horizon_y + y_offset - int(height)))
      else:
        dx = rl.get_random_value(int(min_dx * 0.8), int(max_dx * 0.8))
        curr_x += dx
        pts.append((curr_x, horizon_y + y_offset - rl.get_random_value(0, 20)))
      is_peak = not is_peak

    px = -100
    py = horizon_y + y_offset
    for cx, cy in pts:
      # Black fill
      rl.draw_triangle(
        rl.Vector2(float(px), float(horizon_y + y_offset)),
        rl.Vector2(float(cx), float(horizon_y + y_offset)),
        rl.Vector2(float(px), float(py)),
        bg_color,
      )
      rl.draw_triangle(
        rl.Vector2(float(px), float(py)),
        rl.Vector2(float(cx), float(horizon_y + y_offset)),
        rl.Vector2(float(cx), float(cy)),
        bg_color,
      )
      # Outline
      rl.draw_line_ex(rl.Vector2(float(px), float(py)), rl.Vector2(float(cx), float(cy)), float(line_thick), color)
      px = cx
      py = cy

  # Back layer (taller, wider)
  draw_mountain_layer(
    42,
    rl.Color(180, 0, 100, 255),
    80 if not is_mici else 40,
    150 if not is_mici else 80,
    100,
    300 if not is_mici else 150,
    0,
    2.0 if not is_mici else 1.0,
  )
  # Front layer (shorter, sharper, overlapping)
  draw_mountain_layer(
    99,
    grid_color,
    50 if not is_mici else 30,
    100 if not is_mici else 50,
    50,
    150 if not is_mici else 80,
    0,
    3.0 if not is_mici else 1.5,
  )

  # Draw grid (bottom half)
  num_h_lines = 30 if not is_mici else 20
  spacing = 50.0 if not is_mici else 30.0
  for i in range(num_h_lines + 1):
    f = (i + (grid_offset / spacing)) / num_h_lines
    y = horizon_y + (f ** 2) * (h - horizon_y)

    alpha = int(min(255, 255 * (f * 2.0)))
    line_color = rl.Color(grid_color.r, grid_color.g, grid_color.b, alpha)

    rl.draw_line(0, int(y), w, int(y), line_color)

  num_v_lines = 60 if not is_mici else 30
  for i in range(-num_v_lines, num_v_lines):
    x_bottom = center_x + i * (80 if not is_mici else 50)
    rl.draw_line(center_x, horizon_y, int(x_bottom), h, grid_color)

  # Draw a gradient rectangle over the horizon to fade out the vertical lines smoothly
  fog_height = 200 if not is_mici else 100
  for i in range(fog_height):
    alpha = int(255 * (1.0 - (i / fog_height)))
    fog_color = rl.Color(bg_color.r, bg_color.g, bg_color.b, alpha)
    rl.draw_line(0, horizon_y + i, w, horizon_y + i, fog_color)

  # Add a soft glow to the horizon line
  glow_size = 20 if not is_mici else 10
  for i in range(1, glow_size):
    alpha = int(100 * (1.0 - (i / glow_size)))
    glow_col = rl.Color(horizon_color.r, horizon_color.g, horizon_color.b, alpha)
    rl.draw_line(0, horizon_y - i, w, horizon_y - i, glow_col)
    rl.draw_line(0, horizon_y + i, w, horizon_y + i, glow_col)

  # Draw cyan horizon line with thickness
  rl.draw_line_ex(
    rl.Vector2(float(0), float(horizon_y)),
    rl.Vector2(float(w), float(horizon_y)),
    4.0 if not is_mici else 2.0,
    horizon_color,
  )

  scale = 1.0 if is_mici else 4.0

  # Draw GaryPilot title floating above the Outrun grid
  if gp_texture is not None:
    gp_w = float(int(gp_texture.width * scale))
    gp_h = float(int(gp_texture.height * scale))
    gp_x = float(center_x - int(gp_w / 2))

    # 1. Weightless organic hover float (seamless 4.0s cycle)
    float_amp = 2.0 if is_mici else 8.0
    float_y = math.sin(anim_time * (math.pi / 2.0)) * float_amp
    gp_y = float(horizon_y - (6.0 if is_mici else 24.0)) + float_y

    dest_gp = rl.Rectangle(gp_x, gp_y, gp_w, gp_h)
    source_gp = rl.Rectangle(0.0, 0.0, float(gp_texture.width), float(gp_texture.height))

    # 2. Breathing luminescence pulse (seamless 2.0s cycle)
    glow_pulse = 0.92 + 0.08 * math.sin(anim_time * math.pi)
    tint_alpha = int(255 * glow_pulse)
    rl.draw_texture_pro(
      gp_texture,
      source_gp,
      dest_gp,
      rl.Vector2(0.0, 0.0),
      0.0,
      rl.Color(255, 255, 255, tint_alpha),
    )

    # 3. Specular glint star sparkles on chrome glyph highlights (seamless 4.0s loop)
    cycle_len = 4.0
    cycle_t = anim_time % cycle_len
    sparkle_dur = 0.55
    sparkle_spots = [
      (0.4, 0.10, 0.24),  # 'G' corner
      (2.0, 0.68, 0.22),  # 'P' apex
    ]
    star_base_size = 14.0 if is_mici else 56.0
    for t_start, rx, ry in sparkle_spots:
      dt = cycle_t - t_start
      if 0.0 <= dt < sparkle_dur:
        progress = dt / sparkle_dur
        flare = math.sin(progress * math.pi)
        size = star_base_size * flare
        alpha = min(1.0, flare * 1.5)
        sp_x = gp_x + gp_w * rx
        sp_y = gp_y + gp_h * ry
        draw_diamond_star(sp_x, sp_y, size, alpha)

  # Draw driving pixel art Rivian on the Outrun grid
  if rivian_texture is not None:
    r_w = float(int(rivian_texture.width * scale))
    r_h = float(int(rivian_texture.height * scale))

    # Gentle lane cruise sway (seamless 4.0s loop)
    sway_amp = 6.0 if is_mici else 24.0
    sway_x = math.sin(anim_time * (math.pi / 2.0)) * sway_amp

    # Engine / road suspension micro-rumble
    rumble_y = (1.0 if (int(anim_time * 15.0) % 2 == 1) else 0.0) * (1.0 if is_mici else 2.0)

    r_x = float(center_x - int(r_w / 2)) + sway_x
    bottom_margin = 4.0 if is_mici else 16.0
    r_y = float(h - r_h - bottom_margin) + rumble_y

    # Cyan underbody neon glow cast on the road grid
    ug_pulse = 0.85 + 0.15 * math.sin(anim_time * 4.0)
    rl.draw_circle(
      int(r_x + 38.0 * scale),
      int(r_y + 38.0 * scale),
      28.0 * scale,
      rl.Color(0, 240, 255, int(45 * ug_pulse)),
    )

    # Red taillight ambient glow
    rl.draw_circle(
      int(r_x + 38.0 * scale),
      int(r_y + 19.0 * scale),
      24.0 * scale,
      rl.Color(255, 0, 50, int(50 * ug_pulse)),
    )

    dest_r = rl.Rectangle(r_x, r_y, r_w, r_h)
    source_r = rl.Rectangle(0.0, 0.0, float(rivian_texture.width), float(rivian_texture.height))
    rl.draw_texture_pro(
      rivian_texture,
      source_r,
      dest_r,
      rl.Vector2(0.0, 0.0),
      0.0,
      rl.Color(255, 255, 255, 255),
    )


class ScreenSaverSP(Widget):
  def __init__(self, params: Params | None = None):
    super().__init__()
    self.set_rect(rl.Rectangle(0, 0, gui_app.width, gui_app.height))
    self._params = params or (Params() if Params is not None else None)
    self._is_mici = HARDWARE.get_device_type() == 'mici' or (HARDWARE.get_device_type() == "pc" and os.getenv("BIG") != "1")

    self.logo_path, self.gp_logo_path, self.rivian_path = ensure_screensaver_assets()

    self.texture = None
    self.gp_texture = None
    self.rivian_texture = None
    self._start_time = None
    self._dismiss = False
    self._screensaver_timeout = 300

    # Outrun variables
    self.grid_offset = 0.0
    self.grid_speed = 40.0 if self._is_mici else 80.0

  @property
  def is_active(self) -> bool:
    return self._start_time is not None and not self._dismiss

  @property
  def was_dismissed(self) -> bool:
    return self._dismiss

  def initialize(self):
    self._screensaver_timeout = self._params.get("ScreenSaverTimeout", return_default=True) if self._params is not None else 300
    if self._start_time is None:
      self._start_time = time.monotonic()
    self._dismiss = False
    if self.texture is None:
      self.texture = rl.load_texture(self.logo_path)
    if self.gp_texture is None:
      self.gp_texture = rl.load_texture(self.gp_logo_path)
    if self.rivian_texture is None:
      self.rivian_texture = rl.load_texture(self.rivian_path)

  def hide_event(self):
    super().hide_event()
    self._dismiss = False
    self._start_time = None

  def _handle_mouse_release(self, mouse_pos):
    self._dismiss = True
    self._start_time = None
    gui_app.pop_widget()
    return super()._handle_mouse_release(mouse_pos)

  def _update_state(self):
    super()._update_state()

    if self._start_time and time.monotonic() - self._start_time > self._screensaver_timeout:
      self._dismiss = True
      self._start_time = None

    dt = rl.get_frame_time()
    self.grid_offset += self.grid_speed * dt
    spacing = 50.0 if not self._is_mici else 30.0
    # Wrap offset around spacing for infinite loop effect
    if self.grid_offset > spacing:
      self.grid_offset -= spacing

  def _render(self, rect: rl.Rectangle):
    self.set_rect(rect)
    draw_screensaver(
      int(self.rect.width),
      int(self.rect.height),
      self._is_mici,
      self.grid_offset,
      self.texture,
      self.gp_texture,
      self.rivian_texture,
      time.monotonic(),
    )
    return -1
